  pdxmesh<const Name extends ExactMintName<P>>(
    name: Name,
    def: Omit<PdxmeshDef<Name>, "id">,
    options: { readonly prefix: false }
  ): ContentItem<"pdxmesh", PdxmeshDef<Name>>;
